CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `type` varchar(50) DEFAULT NULL COMMENT 'product:sản phẩm thương; extra: sản phẩm kèm theo',
  `name` varchar(1000) DEFAULT NULL,
  `name_en` varchar(255) DEFAULT NULL,
  `description` mediumtext,
  `description_en` longtext,
  `content` longtext,
  `content_en` longtext,
  `spec_short` text,
  `image` text,
  `cover` varchar(255) DEFAULT NULL,
  `icon` varchar(255) DEFAULT NULL,
  `gallery` longtext,
  `hot` tinyint(1) NOT NULL DEFAULT '0',
  `status` tinyint(1) DEFAULT '0' COMMENT '0: thành công, 1: lưu nháp chờ duyệt, 2: lưu nháp chưa thanh toán',
  `sort` int DEFAULT '0',
  `stock` int DEFAULT '0',
  `price` varchar(50) DEFAULT '0',
  `sale_price` varchar(255) DEFAULT NULL,
  `price_type` varchar(100) DEFAULT 'price' COMMENT 'price: giá; contact: liên hệ',
  `unit_qly` int DEFAULT NULL,
